$os=Get-CimInstance Win32_OperatingSystem;$cs=Get-CimInstance Win32_ComputerSystem;$cpu=@(Get-CimInstance Win32_Processor)[0];"OS    : $($os.Caption) build $($os.BuildNumber)";"HW    : $($cs.Manufacturer)/$($cs.Model)";"CPU   : $($cpu.Name.Trim())";"Cores : $($cs.NumberOfLogicalProcessors) / 6";"RAM   : $([math]::Round($cs.TotalPhysicalMemory/1GB,1))GB / 20";"Disk  : $([math]::Round((Get-PSDrive C).Free/1GB,1))GB / 100";"WSL   : $((wsl --version 2>&1|Select -First 1))";"VT-x  : $($cpu.VirtualizationFirmwareEnabled)  SLAT: $($cpu.SecondLevelAddressTranslationExtensions)  HV: $((Get-ComputerInfo).HyperVisorPresent)";443,8088|%{"Port $_`: $(if($b=Get-NetTCPConnection -LocalPort $_ -State Listen -EA 0){"IN USE by $((Get-Process -Id $b[0].OwningProcess -EA 0).ProcessName)"}else{'free'})"};'Microsoft-Hyper-V','Microsoft-Hyper-V-Management-PowerShell','VirtualMachinePlatform','Microsoft-Windows-Subsystem-Linux','Microsoft-Hyper-V-Online','Microsoft-Hyper-V-Offline','RSAT-Hyper-V-Tools-Feature'|%{"$_ : $((Get-WindowsOptionalFeature -Online -FeatureName $_ -EA 0).State)"};'vds','vmms'|%{$s=Get-Service $_ -EA 0;"$_ : $(if($s){"$($s.Status) / $((Get-CimInstance Win32_Service -Filter "Name='$_'").StartMode)"}else{'NOT INSTALLED'})"}